CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260226170530_InitialCreate') THEN
    CREATE TABLE "Clientes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nome" character varying(200) NOT NULL,
        "Cnpj" character varying(18),
        "Contato" character varying(100),
        "Email" character varying(100),
        "DataCriacao" timestamp with time zone NOT NULL,
        "DataAtualizacao" timestamp with time zone,
        CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260226170530_InitialCreate') THEN
    CREATE TABLE "ModbusConfigs" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nome" character varying(100) NOT NULL,
        "Descricao" character varying(500),
        "IpAddress" character varying(50) NOT NULL,
        "Port" integer NOT NULL,
        "SlaveId" smallint NOT NULL,
        "FuncaoModbus" character varying(20) NOT NULL,
        "EnderecoRegistro" integer NOT NULL,
        "QuantidadeRegistros" integer NOT NULL,
        "TipoDado" character varying(20) NOT NULL,
        "ByteOrder" character varying(10) NOT NULL,
        "FatorConversao" numeric(10,6),
        "Offset" numeric(10,6),
        "Unidade" character varying(20),
        "OrdemLeitura" integer NOT NULL,
        "Ativo" boolean NOT NULL,
        "DataCriacao" timestamp with time zone NOT NULL,
        "DataAtualizacao" timestamp with time zone,
        CONSTRAINT "PK_ModbusConfigs" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

