DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260226170530_InitialCreate') THEN
    CREATE TABLE "Cilindros" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nome" character varying(200) NOT NULL,
        "Descricao" character varying(1000),
        "CodigoCliente" character varying(50) NOT NULL,
        "CodigoInterno" character varying(50) NOT NULL,
        "Modelo" character varying(100),
        "Fabricante" character varying(100),
        "DataFabricacao" timestamp with time zone,
        "DiametroInterno" numeric(10,2),
        "ComprimentoHaste" numeric(10,2),
        "DiametroHaste" numeric(10,2),
        "MaximaPressaoSuportadaA" numeric(10,2),
        "MaximaPressaoSuportadaB" numeric(10,2),
        "MaximaPressaoSegurancaA" numeric(10,2),
        "MaximaPressaoSegurancaB" numeric(10,2),
        "PreCargaA" numeric(10,2),
        "CargaNominalA" numeric(10,2),
        "TempoRampaSubidaA" numeric(10,2),
        "TempoDuracaoCargaA" numeric(10,2),
        "TempoRampaDescidaA" numeric(10,2),
        "PercentualVariacaoAlarmeA" numeric(10,2),
        "HistereseAlarmeA" numeric(10,2),
        "PercentualVariacaoDesligaProcessoA" numeric(10,2),
        "PreCargaB" numeric(10,2),
        "CargaNominalB" numeric(10,2),
        "TempoRampaSubidaB" numeric(10,2),
        "TempoDuracaoCargaB" numeric(10,2),
        "TempoRampaDescidaB" numeric(10,2),
        "PercentualVariacaoAlarmeB" numeric(10,2),
        "HistereseAlarmeB" numeric(10,2),
        "PercentualVariacaoDesligaProcessoB" numeric(10,2),
        "ClienteId" integer NOT NULL,
        "DataCriacao" timestamp with time zone NOT NULL,
        "DataAtualizacao" timestamp with time zone,
        CONSTRAINT "PK_Cilindros" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Cilindros_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

